import base64,json,os,pathlib,subprocess,tempfile,signal
root=pathlib.Path(tempfile.mkdtemp(prefix='b1k-static-'))
f=root/'probe.py';f.write_bytes(base64.b64decode(''))
env=dict(os.environ);env['OMP_NUM_THREADS']='1';env['PYTHONNOUSERSITE']='1'
for key in ['MASTER_ADDR','MASTER_PORT','RANK','WORLD_SIZE','LOCAL_RANK','LOCAL_WORLD_SIZE','TORCHELASTIC_RUN_ID']:
 env.pop(key,None)
cmd=['/mnt/afs/260010165/behavior_1k/runtime_20261007_1306/envs/b1k-pi05/bin/python','-m','torch.distributed.run','--rdzv_backend=static','--master_addr=127.0.0.1','--master_port=29579','--nnodes=1','--node_rank=0','--nproc_per_node=4',str(f)]
p=subprocess.Popen(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,start_new_session=True)
try:output=p.communicate(timeout=42)[0]
except subprocess.TimeoutExpired:
 os.killpg(p.pid,signal.SIGKILL);output=p.communicate()[0]
result={'passed':False,'returncode':p.returncode,'tail':output[-5000:]}
for line in output.splitlines():
 if line.startswith('B1K_COMM_RESULT '):result=json.loads(line.split(' ',1)[1])
print('B1KPROBE_BEGIN'+base64.b64encode(json.dumps(result).encode()).decode()+'B1KPROBE_END')
